        def items = []
        jobs.eachWithIndex { job, i ->
            heads[(i + 1).toString()] = (i + 1).toString() * 40
            def item = submit(job, 600, i == 3 ? [:] : [CANDIDATE_PR: (i + 1).toString()])
            items << item
            pending(item, heads[(i + 1).toString()], contexts[i])
